#pragma once

#include <stddef.h>
#include <stdint.h>

#include "ai_inference_model_data.h"

/*
 * Active TinyML model: parking occupancy classifier, trained on CNRPark
 * 150x150 slot patches with transfer learning. The weights live in
 * ai_inference_vehicle_model.c (generated by train_occupancy_tl.py,
 * len = 657088 bytes, full-int8).
 *
 * Input [1,160,160,1] int8 luma; output [1,2] int8 softmax where index 1 is
 * the occupied-slot confidence. The classification postprocess emits a single
 * detection when target_class_index clears the threshold, and raw_score drives
 * the presence state machine. When TFLM cannot load this model at runtime,
 * ai_inference.c transparently falls back to the frame-difference motion
 * detector.
 */
extern const unsigned char g_vehicle_fomo_model_data[];

static const ai_inference_model_asset_t g_ai_inference_generated_model_asset = {
    .data = g_vehicle_fomo_model_data,
    .len = 657088U,
    .tensor_arena_size = 1024U * 1024U,
    .input_width = 160U,
    .input_height = 160U,
    .detection_threshold = 204U,
    .class_count = 2U,
    .background_index = 0xFFU,
    .target_class_index = 1U,
    .output_type = AI_INFERENCE_OUTPUT_CLASSIFICATION,
};
